[{"order":1,"type":"heading","text":"JUnit Mocking Framework Integration: MockitoExtension and Static Mocking"},{"order":2,"type":"paragraph","text":"Modern Java testing relies heavily on the combination of JUnit 5 and Mockito. This tutorial explores advanced integration techniques using MockitoExtension to manage mock lifecycles and Mockito's static mocking capabilities for handling legacy or static utility classes."},{"order":3,"type":"subheading","text":"Prerequisites and Setup"},{"order":4,"type":"paragraph","text":"To use MockitoExtension and static mocking, ensure your build configuration includes JUnit 5 and Mockito version 3.4.0 or higher (which natively introduced inline static mocking)."},{"order":5,"type":"code","text":"testImplementation 'org.junit.jupiter:junit-jupiter:5.9.2'
testImplementation 'org.mockito:mockito-core:5.3.1'
testImplementation 'org.mockito:mockito-junit-jupiter:5.3.1'"},{"order":6,"type":"subheading","text":"Using MockitoExtension"},{"order":7,"type":"paragraph","text":"Traditionally, developers had to manually call MockitoAnnotations.openMocks(this) in a @BeforeEach method. The @ExtendWith(MockitoExtension.class) annotation automates the initialization of fields annotated with @Mock, @Spy, @Captor, and @InjectMocks."},{"order":8,"type":"code","text":"@ExtendWith(MockitoExtension.class)
public class UserServiceTest {

    @Mock
    private UserRepository userRepository;

    @InjectMocks
    private UserService userService;

    @Test
    public void testFindUser() {
        when(userRepository.findById(1L)).thenReturn(Optional.of(new User(1L, "Alice")));
        User user = userService.getUser(1L);
        assertEquals("Alice", user.getName());
    }
}"},{"order":9,"type":"subheading","text":"Static Mocking with Mockito"},{"order":10,"type":"paragraph","text":"There are times when code relies on static utility methods (such as LocalDate.now() or database utility loaders) that cannot be directly injected. Mockito.mockStatic() provides a way to mock static method calls within a specific scope using try-with-resources blocks."},{"order":11,"type":"code","text":"public class BillingUtils {
    public static boolean isTaxHoliday() {
        // Complex external check
        return false;
    }
}

@ExtendWith(MockitoExtension.class)
public class BillingServiceTest {

    @Test
    public void testServiceWithStaticMock() {
        try (MockedStatic<BillingUtils> mockedStatic = Mockito.mockStatic(BillingUtils.class)) {
            mockedStatic.when(BillingUtils::isTaxHoliday).thenReturn(true);

            assertTrue(BillingUtils.isTaxHoliday());
            // Execute service method that relies on the static utility
        }
        // Static mock is automatically deregistered outside the try block
    }
}"},{"order":12,"type":"subheading","text":"Best Practices"},{"order":13,"type":"bullet_point","text":"Always scope static mocks using try-with-resources to prevent state leakage between tests."},{"order":14,"type":"bullet_point","text":"Prefer dependency injection over static mocking whenever possible to keep code testable and loosely coupled."},{"order":15,"type":"bullet_point","text":"Use @ExtendWith(MockitoExtension.class) to eliminate boilerplate mock initialization code."}]
